//! Shared rendering primitives and the `Format` façade of stateless helpers.
//!
//! Every percentage in this crate is computed and scaled in `f32` before being
//! handed to the formatter. That is deliberate: the original C++ stored ratios
//! in `float` and only widened to `double` at the `operator<<` boundary, so the
//! single-precision rounding is observable. `0.12345f * 100.0f` lands on
//! `12.345000267...`, which prints as `12.35` at two decimals rather than the
//! `12.34` an `f64` computation would produce.

/// Cell count used by a bar that was never given an explicit width.
pub const DEFAULT_WIDTH: usize = 50;

/// Decimal places used by every percentage that does not carry its own.
pub const DEFAULT_PRECISION: usize = 1;

/// Braille spinner cycle stepped through by `CyclicProgress`.
pub const SPINNER_FRAMES: [&str; 8] = ["⣾", "⣽", "⣻", "⢿", "⡿", "⣟", "⣯", "⣷"];

/// Completion ratio in `0.0..=1.0+`, in `f32` to match the C++ arithmetic.
///
/// An empty total yields `0.0` instead of a NaN, so callers never have to guard.
pub fn ratio(current: u64, total: u64) -> f32 {
    if total == 0 {
        0.0
    } else {
        current as f32 / total as f32
    }
}

/// Renders a `0.0..=1.0` fraction as a percentage with `precision` decimals.
pub fn percent_string(fraction: f32, precision: usize) -> String {
    format!("{:.*}%", precision, fraction * 100.0)
}

/// Renders `current`/`total` as a percentage with `precision` decimals.
pub fn ratio_string(current: u64, total: u64, precision: usize) -> String {
    percent_string(ratio(current, total), precision)
}

/// Number of filled `=` cells for a bar of `width` columns.
///
/// Kept in integer arithmetic so the truncation is exact: a float `width * ratio`
/// can land just under a whole cell (8.2499994 instead of 8.25) and lose a tick.
pub fn filled_cells(current: u64, total: u64, width: usize) -> usize {
    if total == 0 {
        return 0;
    }
    let done = current.min(total);
    ((width as u64).saturating_mul(done) / total) as usize
}

/// Renders `[===>   ] 50.0%`, where the bracketed run is exactly `width` columns.
///
/// The head `>` occupies one of the unfilled columns, so it disappears once the
/// bar is full and the interior stays width-stable at every ratio.
pub fn render_bar(current: u64, total: u64, width: usize) -> String {
    let filled = filled_cells(current, total, width);
    let mut out = String::with_capacity(width + 10);
    out.push('[');
    for _ in 0..filled {
        out.push('=');
    }
    if filled < width {
        out.push('>');
        for _ in 0..width - filled - 1 {
            out.push(' ');
        }
    }
    out.push_str("] ");
    out.push_str(&ratio_string(current, total, DEFAULT_PRECISION));
    out
}

/// Stateless formatting entry points, mirroring the C++ `Format` static methods.
pub struct Format;

impl Format {
    /// `Format::percentage(0.33)` -> `33.0%`, at the default precision.
    pub fn percentage(fraction: f32) -> String {
        Self::percentage_with(fraction, DEFAULT_PRECISION)
    }

    /// `Format::percentage(0.12345, 3)` -> `12.345%`.
    pub fn percentage_with(fraction: f32, precision: usize) -> String {
        percent_string(fraction, precision)
    }

    /// `Format::progress(33, 100)` -> `33/100`.
    pub fn progress(current: u64, total: u64) -> String {
        format!("{}/{}", current, total)
    }

    /// `Format::bar(33, 100, 25)` -> `[========>                ] 33.0%`.
    pub fn bar(current: u64, total: u64, width: usize) -> String {
        render_bar(current, total, width)
    }

    /// [`Format::bar`] at [`DEFAULT_WIDTH`].
    pub fn bar_default(current: u64, total: u64) -> String {
        render_bar(current, total, DEFAULT_WIDTH)
    }
}

