//! The single-line progress bar.

use super::format::{render_bar, ratio, DEFAULT_WIDTH};
use std::fmt;

/// A bar over a `current`/`total` pair, rendered into a fixed number of columns.
#[derive(Clone, Debug, PartialEq)]
pub struct ProgressBar {
    progress: u64,
    total: u64,
    width: usize,
}

impl ProgressBar {
    /// A bar at zero progress over a total of 100, [`DEFAULT_WIDTH`] columns wide.
    pub fn new() -> Self {
        Self {
            progress: 0,
            total: 100,
            width: DEFAULT_WIDTH,
        }
    }

    pub fn set_progress(&mut self, progress: u64) -> &mut Self {
        self.progress = progress;
        self
    }

    pub fn set_total(&mut self, total: u64) -> &mut Self {
        self.total = total;
        self
    }

    pub fn set_width(&mut self, width: usize) -> &mut Self {
        self.width = width;
        self
    }

    pub fn progress(&self) -> u64 {
        self.progress
    }

    pub fn total(&self) -> u64 {
        self.total
    }

    pub fn width(&self) -> usize {
        self.width
    }

    /// Completion ratio in `0.0..=1.0`.
    pub fn fraction(&self) -> f32 {
        ratio(self.progress, self.total)
    }

    /// The rendered bar, e.g. `[====>     ] 50.0%`.
    pub fn str(&self) -> String {
        render_bar(self.progress, self.total, self.width)
    }

    /// Alias for [`ProgressBar::str`], standing in for the C++ `operator()`.
    pub fn call(&self) -> String {
        self.str()
    }
}

impl Default for ProgressBar {
    fn default() -> Self {
        Self::new()
    }
}

impl fmt::Display for ProgressBar {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.str())
    }
}

impl From<ProgressBar> for String {
    fn from(bar: ProgressBar) -> Self {
        bar.str()
    }
}

