//! A stack of bars rendered as one block of numbered lines.

use super::bar::ProgressBar;
use std::fmt;

/// Collects bars and renders them as `Bar 1: ...`, `Bar 2: ...`, one per line.
#[derive(Clone, Debug, Default)]
pub struct MultiProgress {
    bars: Vec<ProgressBar>,
}

impl MultiProgress {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn add_bar(&mut self, bar: ProgressBar) -> &mut Self {
        self.bars.push(bar);
        self
    }

    pub fn len(&self) -> usize {
        self.bars.len()
    }

    pub fn is_empty(&self) -> bool {
        self.bars.is_empty()
    }

    pub fn bars(&self) -> &[ProgressBar] {
        &self.bars
    }

    /// Mutable access so a caller can advance a bar already handed over.
    pub fn bar_mut(&mut self, index: usize) -> Option<&mut ProgressBar> {
        self.bars.get_mut(index)
    }

    /// The numbered block, newline-separated with no trailing newline.
    pub fn str(&self) -> String {
        let mut out = String::new();
        for (i, bar) in self.bars.iter().enumerate() {
            if i > 0 {
                out.push('\n');
            }
            out.push_str(&format!("Bar {}: {}", i + 1, bar.str()));
        }
        out
    }
}

impl fmt::Display for MultiProgress {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.str())
    }
}

