use super::bar::ProgressBar;
use super::format::{ratio_string, DEFAULT_PRECISION, DEFAULT_WIDTH};

/// Accumulates bar settings and, on [`build`](ProgressBuilder::build), renders
/// the configured ratio as a percentage.
#[derive(Clone, Debug, PartialEq)]
pub struct ProgressBuilder {
    progress: u64,
    total: u64,
    width: usize,
    precision: usize,
}

impl ProgressBuilder {
    pub fn new() -> Self {
        Self {
            progress: 0,
            total: 100,
            width: DEFAULT_WIDTH,
            precision: DEFAULT_PRECISION,
        }
    }

    pub fn set_progress(&mut self, progress: u64) -> &mut Self {
        self.progress = progress;
        self
    }

    pub fn set_total(&mut self, total: u64) -> &mut Self {
        self.total = total;
        self
    }

    pub fn set_width(&mut self, width: usize) -> &mut Self {
        self.width = width;
        self
    }

    pub fn set_precision(&mut self, precision: usize) -> &mut Self {
        self.precision = precision;
        self
    }

    /// The configured ratio as a percentage, e.g. `50.0%`.
    pub fn build(&self) -> String {
        ratio_string(self.progress, self.total, self.precision)
    }

    /// The same settings as a full [`ProgressBar`], for callers that want the bar.
    pub fn build_bar(&self) -> ProgressBar {
        let mut bar = ProgressBar::new();
        bar.set_progress(self.progress)
            .set_total(self.total)
            .set_width(self.width);
        bar
    }
}

impl Default for ProgressBuilder {
    fn default() -> Self {
        Self::new()
    }
}

