//! A mutable counter that renders a labelled percentage-and-count line.

use super::format::{ratio, ratio_string, DEFAULT_PRECISION};
use std::fmt;

/// Owns a running `current` against a fixed `total`, advanced by
/// [`update`](ProgressDisplay::update) or [`increment`](ProgressDisplay::increment).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ProgressDisplay {
    current: u64,
    total: u64,
}

impl ProgressDisplay {
    /// A display at zero progress over `total`.
    pub fn new(total: u64) -> Self {
        Self { current: 0, total }
    }

    /// Jumps to an absolute position.
    pub fn update(&mut self, current: u64) -> &mut Self {
        self.current = current;
        self
    }

    /// Advances by `delta` from wherever the display currently sits.
    pub fn increment(&mut self, delta: u64) -> &mut Self {
        self.current = self.current.saturating_add(delta);
        self
    }

    pub fn current(&self) -> u64 {
        self.current
    }

    pub fn total(&self) -> u64 {
        self.total
    }

    /// Completion ratio in `0.0..=1.0`.
    pub fn fraction(&self) -> f32 {
        ratio(self.current, self.total)
    }

    /// The rendered line, e.g. `Progress: 50.0% (50/100)`.
    pub fn display(&self) -> String {
        format!(
            "Progress: {} ({}/{})",
            ratio_string(self.current, self.total, DEFAULT_PRECISION),
            self.current,
            self.total
        )
    }
}

impl fmt::Display for ProgressDisplay {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.display())
    }
}

