//! A spinner that wraps around once it reaches its total.

use super::format::{ratio, ratio_string, DEFAULT_PRECISION, SPINNER_FRAMES};
use std::fmt;

/// Steps a braille spinner alongside a position that cycles through `0..total`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct CyclicProgress {
    current: u64,
    total: u64,
}

impl CyclicProgress {
    /// A spinner at position zero with a cycle length of `total`.
    pub fn new(total: u64) -> Self {
        Self { current: 0, total }
    }

    /// Advances one position, wrapping back to zero at the end of the cycle.
    pub fn next(&mut self) -> &mut Self {
        let span = self.total.max(1);
        self.current = (self.current + 1) % span;
        self
    }

    /// Resets to position zero.
    pub fn reset(&mut self) -> &mut Self {
        self.current = 0;
        self
    }

    pub fn current(&self) -> u64 {
        self.current
    }

    pub fn total(&self) -> u64 {
        self.total
    }

    /// The spinner glyph for the current position.
    pub fn frame(&self) -> &'static str {
        SPINNER_FRAMES[(self.current % SPINNER_FRAMES.len() as u64) as usize]
    }

    /// Completion ratio in `0.0..=1.0`.
    pub fn fraction(&self) -> f32 {
        ratio(self.current, self.total)
    }

    /// The rendered spinner, e.g. `⣻ 20.0%`.
    pub fn str(&self) -> String {
        format!(
            "{} {}",
            self.frame(),
            ratio_string(self.current, self.total, DEFAULT_PRECISION)
        )
    }
}

impl fmt::Display for CyclicProgress {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.str())
    }
}

