use super::format::{ratio, ratio_string, DEFAULT_PRECISION};
use std::fmt;

/// Pairs a task name with how many of its `total` units are done.
#[derive(Clone, Debug, PartialEq)]
pub struct TaskProgress {
    name: String,
    completed: u64,
    total: u64,
}

impl TaskProgress {
    /// `TaskProgress::new("Test", 10)` starts at zero of ten units.
    pub fn new(name: &str, total: u64) -> Self {
        Self {
            name: name.to_string(),
            completed: 0,
            total,
        }
    }

    /// Records `units` more as finished.
    pub fn complete(&mut self, units: u64) -> &mut Self {
        self.completed = self.completed.saturating_add(units);
        self
    }

    /// Marks every unit finished.
    pub fn finish(&mut self) -> &mut Self {
        self.completed = self.total;
        self
    }

    pub fn name(&self) -> &str {
        &self.name
    }

    pub fn completed(&self) -> u64 {
        self.completed
    }

    pub fn total(&self) -> u64 {
        self.total
    }

    pub fn is_done(&self) -> bool {
        self.completed >= self.total
    }

    /// Completion ratio in `0.0..=1.0`.
    pub fn fraction(&self) -> f32 {
        ratio(self.completed, self.total)
    }

    /// The rendered status line, e.g. `Test: 3/10 - 30.0%`.
