        format!(
            "{}: {}/{} - {}",
            self.name,
            self.completed,
            self.total,
            ratio_string(self.completed, self.total, DEFAULT_PRECISION)
        )
    }
}

impl fmt::Display for TaskProgress {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.status())
