use indicators::*;

fn main() {
    // zero total, over-full, zero width: all reachable through the public API
    println!("z0 [{}]", Format::bar(0, 0, 10));
    println!("z1 [{}]", Format::bar(5, 0, 10));
    println!("w0 [{}]", Format::bar(5, 10, 0));
    println!("of [{}]", Format::bar(150, 100, 10));
    println!("ex [{}]", Format::bar(100, 100, 10));
    println!("lo [{}]", Format::bar(1, 100, 10));
    println!("pg [{}]", Format::progress(0, 0));
    let mut c = CyclicProgress::new(0);
    for _ in 0..3 { c.next(); }
    println!("cy [{}]", c.str());
    let mut c2 = CyclicProgress::new(3);
    for i in 0..7 { c2.next(); print!("{}:[{}] ", i, c2.str()); }
    println!();
    let mut d = ProgressDisplay::new(0);
    d.increment(u64::MAX); d.increment(5); // saturating, must not panic
    println!("ds [{}]", d.display());
    let mut t = TaskProgress::new("", 0);
    t.complete(0);
    println!("tk [{}]", t.status());
    let mut tr = ProgressTracker::new();
    println!("tr0 [{}] [{}]", tr.get_progress(), tr.get_percentage());
    tr.add_stage("only");
    println!("tr1 [{}] stage={:?}", tr.get_progress(), tr.current_stage());
    println!("mp [{}]", MultiProgress::new().str());
