    for w in [1usize, 2, 7] {
        for cur in 0..=w as u64 {
            let s = Format::bar(cur, w as u64, w);
            let inner = s.find(']').unwrap() - s.find('[').unwrap() - 1;
            assert_eq!(inner, w, "width drift at {}/{} w={}: {}", cur, w, w, s);
        }
    }
    println!("width-stability: OK");
}
